#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char riga[128];
    double serbatoio_a = 0.0, serbatoio_b = 0.0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%lf %lf %c", &serbatoio_a, &serbatoio_b, &extra) != 2 ||
        serbatoio_a < 0.0 || serbatoio_b < 0.0) {
        fprintf(stderr, "Errore: livelli iniziali non validi.\n");
        return EXIT_FAILURE;
    }

    double *attivo = &serbatoio_a;
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        char cmd = '\0', bersaglio = '\0';
        double delta = 0.0;
        if (sscanf(riga, " %c", &cmd) != 1) {
            continue;
        }
        if (cmd == 'S' && sscanf(riga, " S %c %c", &bersaglio, &extra) == 1) {
            if (bersaglio == 'A') { attivo = &serbatoio_a; }
            else if (bersaglio == 'B') { attivo = &serbatoio_b; }
            else {
                fprintf(stderr, "Errore: serbatoio sconosciuto.\n");
                return EXIT_FAILURE;
            }
        } else if (cmd == 'A' && sscanf(riga, " A %lf %c", &delta, &extra) == 1) {
            *attivo += delta;
            if (*attivo < 0.0) { *attivo = 0.0; }
        } else if (cmd == 'D' && sscanf(riga, " %c %c", &cmd, &extra) == 1) {
            *attivo *= 2.0;
        } else {
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }

    char nome_attivo = (attivo == &serbatoio_a) ? 'A' : 'B';
    printf("Serbatoio attivo: %c\n", nome_attivo);
    printf("Livello attivo (*attivo): %.2f L\n", *attivo);
    printf("Serbatoio A: %.2f L\n", serbatoio_a);
    printf("Serbatoio B: %.2f L\n", serbatoio_b);
    return EXIT_SUCCESS;
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

int *trova_massimo(int dati[], size_t n);
int *trova_primo_oltre_soglia(int dati[], size_t n, int soglia);

int main(void) {
    constexpr size_t MAX_ELEM = 20;
    int misure[MAX_ELEM] = {0};
    char riga[128];
    int n_in = 0, soglia = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %c", &n_in, &soglia, &extra) != 2 ||
        n_in < 0 || n_in > (int)MAX_ELEM) {
        fprintf(stderr, "Errore: parametri non validi (n in 0..20).\n");
        return EXIT_FAILURE;
    }
    size_t n = (size_t)n_in;
    for (size_t i = 0; i < n; ++i) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%d %c", &misure[i], &extra) != 1) {
            fprintf(stderr, "Errore: misura non valida.\n");
            return EXIT_FAILURE;
        }
    }

    int *p_max = trova_massimo(misure, n);
    if (p_max != nullptr) {
        printf("Massimo: %d\n", *p_max);
    } else {
        printf("Massimo: nessuno (array vuoto)\n");
    }

    int *p_oltre = trova_primo_oltre_soglia(misure, n, soglia);
    if (p_oltre != nullptr) {
        printf("Primo oltre soglia: %d\n", *p_oltre);
        *p_oltre = soglia;
        printf("Dati aggiornati:");
        for (size_t i = 0; i < n; ++i) { printf(" %d", misure[i]); }
        putchar('\n');
    } else {
        printf("Oltre soglia: nessuno\n");
    }
    return EXIT_SUCCESS;
}

int *trova_massimo(int dati[], size_t n) {
    if (n == 0) { return nullptr; }
    int *migliore = &dati[0];
    for (size_t i = 1; i < n; ++i) {
        if (dati[i] > *migliore) { migliore = &dati[i]; }
    }
    return migliore;
}

int *trova_primo_oltre_soglia(int dati[], size_t n, int soglia) {
    for (size_t i = 0; i < n; ++i) {
        if (dati[i] > soglia) { return &dati[i]; }
    }
    return nullptr;
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

int somma_finestra(const int *inizio, size_t k);
void stampa_sequenza(const int *p, size_t n);

int main(void) {
    constexpr size_t MAX_DATI = 30;
    int dati[MAX_DATI] = {0};
    char riga[128];
    int n_in = 0, k_in = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %c", &n_in, &k_in, &extra) != 2 ||
        n_in < 1 || n_in > (int)MAX_DATI || k_in < 1 || k_in > n_in) {
        fprintf(stderr, "Errore: parametri n e k non validi.\n");
        return EXIT_FAILURE;
    }
    size_t n = (size_t)n_in, k = (size_t)k_in;
    for (size_t i = 0; i < n; ++i) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%d %c", &dati[i], &extra) != 1 ||
            dati[i] < -10'000 || dati[i] > 10'000) {
            fprintf(stderr, "Errore: valore non valido.\n");
            return EXIT_FAILURE;
        }
    }

    printf("Serie: ");
    stampa_sequenza(dati, n);
    const int *migliore = &dati[0];
    int somma_max = somma_finestra(migliore, k);
    for (size_t i = 0; i <= n - k; ++i) {
        const int *finestra = &dati[i];
        int somma = somma_finestra(finestra, k);
        printf("Finestra %zu: somma=%d\n", i, somma);
        if (somma > somma_max) {
            somma_max = somma;
            migliore = finestra;
        }
    }
    printf("Somma massima: %d\n", somma_max);
    printf("Finestra migliore: ");
    stampa_sequenza(migliore, k);
    return EXIT_SUCCESS;
}

int somma_finestra(const int *inizio, size_t k) {
    int somma = 0;
    for (size_t i = 0; i < k; ++i) {
        somma += *(inizio + i);
    }
    return somma;
}

void stampa_sequenza(const int *p, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (i > 0) { putchar(' '); }
        printf("%d", p[i]);
    }
    putchar('\n');
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

ptrdiff_t lunghezza_ptr(const char *s);
void inverti_intervallo(char *inizio, char *fine);

int main(void) {
    char testo[128], riga_s[32];
    char sep = '\0', extra = '\0';
    if (fgets(testo, (int)sizeof(testo), stdin) == nullptr ||
        fgets(riga_s, (int)sizeof(riga_s), stdin) == nullptr ||
        sscanf(riga_s, " %c %c", &sep, &extra) != 1) {
        fprintf(stderr, "Errore: input non valido.\n");
        return EXIT_FAILURE;
    }
    testo[strcspn(testo, "\n")] = '\0';
    ptrdiff_t len = lunghezza_ptr(testo);
    printf("Lunghezza: %td\n", len);

    char *prima = strchr(testo, (unsigned char)sep);
    if (prima == nullptr) {
        printf("Delimitatore '%c' assente.\n", sep);
        inverti_intervallo(testo, testo + len);
        printf("Risultato: %s\n", testo);
        return EXIT_SUCCESS;
    }
    char *ultima = strrchr(testo, (unsigned char)sep);
    int occ = 0;
    const char *cur = prima;
    while ((cur = strchr(cur, (unsigned char)sep)) != nullptr) {
        ++occ;
        ++cur;
    }
    printf("Occorrenze di '%c': %d\n", sep, occ);
    printf("Prima: %td, ultima: %td, distanza: %td\n",
           prima - testo, ultima - testo, ultima - prima);
    if (ultima > prima + 1) {
        inverti_intervallo(prima + 1, ultima);
    }
    printf("Risultato: %s\n", testo);
    return EXIT_SUCCESS;
}

ptrdiff_t lunghezza_ptr(const char *s) {
    const char *p = s;
    while (*p != '\0') { ++p; }
    return p - s;
}

void inverti_intervallo(char *inizio, char *fine) {
    char *sx = inizio;
    char *dx = fine;
    while (sx < dx) {
        --dx;
        char tmp = *sx;
        *sx = *dx;
        *dx = tmp;
        ++sx;
    }
}

#include <stdio.h>
#include <stdlib.h>

void scambia_int(int *a, int *b);
void ordina_tre(int *a, int *b, int *c);
bool scomponi_secondi(int secondi_totali, int *ore, int *minuti, int *secondi);

int main(void) {
    char riga[128];
    int t1 = 0, t2 = 0, t3 = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %d %c", &t1, &t2, &t3, &extra) != 3 ||
        t1 < 0 || t1 > 86'399 || t2 < 0 || t2 > 86'399 || t3 < 0 || t3 > 86'399) {
        fprintf(stderr, "Errore: tempi non validi (0..86399).\n");
        return EXIT_FAILURE;
    }

    ordina_tre(&t1, &t2, &t3);
    int tempi[3] = {t1, t2, t3};
    for (int i = 0; i < 3; ++i) {
        int h = 0, m = 0, s = 0;
        scomponi_secondi(tempi[i], &h, &m, &s);
        printf("%do tempo: %02d:%02d:%02d (%d s)\n", i + 1, h, m, s, tempi[i]);
    }
    int dh = 0, dm = 0, ds = 0, sec_med = 0;
    scomponi_secondi(t3 - t1, &dh, &dm, &ds);
    scomponi_secondi(t2, nullptr, nullptr, &sec_med);
    printf("Distacco primo-ultimo: %02d:%02d:%02d (%d s)\n", dh, dm, ds, t3 - t1);
    printf("Secondi residui del mediano: %d\n", sec_med);
    return EXIT_SUCCESS;
}

void scambia_int(int *a, int *b) {
    if (a == nullptr || b == nullptr) { return; }
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

void ordina_tre(int *a, int *b, int *c) {
    if (a == nullptr || b == nullptr || c == nullptr) { return; }
    if (*a > *b) { scambia_int(a, b); }
    if (*b > *c) { scambia_int(b, c); }
    if (*a > *b) { scambia_int(a, b); }
}

bool scomponi_secondi(int secondi_totali, int *ore, int *minuti, int *secondi) {
    if (secondi_totali < 0) { return false; }
    if (ore != nullptr) { *ore = secondi_totali / 3600; }
    if (minuti != nullptr) { *minuti = (secondi_totali % 3600) / 60; }
    if (secondi != nullptr) { *secondi = secondi_totali % 60; }
    return true;
}

#include <ctype.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

const char *trova_valore(const char *riga, const char *chiave_attesa);
bool copia_trim(const char *inizio, char *const dest, size_t cap, ptrdiff_t *lunghezza_out);

int main(void) {
    char chiave[32], riga[128], valore[32];
    if (fgets(chiave, (int)sizeof(chiave), stdin) == nullptr) {
        fprintf(stderr, "Errore: chiave mancante.\n");
        return EXIT_FAILURE;
    }
    chiave[strcspn(chiave, "\n")] = '\0';
    if (chiave[0] == '\0') {
        fprintf(stderr, "Errore: chiave vuota.\n");
        return EXIT_FAILURE;
    }
    int num_riga = 0, trovate = 0;
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        ++num_riga;
        riga[strcspn(riga, "\n")] = '\0';
        const char *val = trova_valore(riga, chiave);
        if (val == nullptr) { continue; }
        ptrdiff_t len = 0;
        if (copia_trim(val, valore, sizeof(valore), &len)) {
            ++trovate;
            printf("Riga %d: [%s] (len=%td)\n", num_riga, valore, len);
        } else {
            printf("Riga %d: valore troppo lungo\n", num_riga);
        }
    }
    printf("Corrispondenze trovate: %d\n", trovate);
    return EXIT_SUCCESS;
}

const char *trova_valore(const char *riga, const char *chiave_attesa) {
    if (riga == nullptr || chiave_attesa == nullptr) { return nullptr; }
    const char *eq = strchr(riga, '=');
    if (eq == nullptr) { return nullptr; }
    size_t len_chiave = strlen(chiave_attesa);
    if ((size_t)(eq - riga) != len_chiave || strncmp(riga, chiave_attesa, len_chiave) != 0) {
        return nullptr;
    }
    return eq + 1;
}

bool copia_trim(const char *inizio, char *const dest, size_t cap, ptrdiff_t *lunghezza_out) {
    if (inizio == nullptr || dest == nullptr || cap == 0) { return false; }
    while (*inizio != '\0' && isspace((unsigned char)*inizio)) { ++inizio; }
    const char *fine = inizio + strlen(inizio);
    while (fine > inizio && isspace((unsigned char)*(fine - 1))) { --fine; }
    ptrdiff_t len = fine - inizio;
    if ((size_t)len >= cap) { return false; }
    char *d = dest;
    for (const char *s = inizio; s < fine; ++s) { *d++ = *s; }
    *d = '\0';
    if (lunghezza_out != nullptr) { *lunghezza_out = len; }
    return true;
}
